// JavaScript principal minifié
document.addEventListener('DOMContentLoaded',()=>{const e=document.getElementById('mobile-menu-button'),t=document.getElementById('mobile-menu');e&&(e.addEventListener('click',()=>{t.classList.toggle('hidden'),e.setAttribute('aria-expanded',t.classList.contains('hidden')?'false':'true')}),document.querySelectorAll('a[href^="#"]').forEach(a=>{a.addEventListener('click',function(s){s.preventDefault();const o=this.getAttribute('href');if('#'!==o){const l=document.querySelector(o);if(l){t.classList.add('hidden'),e.setAttribute('aria-expanded','false');const n=document.querySelector('header').offsetHeight,i=l.offsetTop-n;window.scrollTo({top:i,behavior:'smooth'})}}})}))});